const BASE: MetalMaterial = {
  colorBack: [0, 0, 0, 0],
  colorTint: [1, 1, 1, 0],
  speed: 1,
  repetition: 1.5,
  softness: 0.05,
  shiftRed: 0.3,
  shiftBlue: 0.3,
  distortion: 0.1,
  contour: 0.4,
  angle: 90,
  shaderOpacity: 1,
};

export function presetMaterial(preset: MetalPreset, theme: MetalTheme): MetalMaterial {
  switch (preset) {
    case 'chromatic':
      return theme === 'dark'
        ? { ...BASE, colorTint: rgba('#88ccff2e'), shiftRed: 0.75, shiftBlue: 0.75, repetition: 2, softness: 0.09 }
