    case 'silver':
      return theme === 'dark'
        ? { ...BASE, colorTint: rgba('#ffffff66'), shaderOpacity: 0.88 }
        : { ...BASE, colorTint: rgba('#ffffff40') };
    case 'gold':
      return theme === 'dark'
        ? { ...BASE, colorTint: rgba('#ffcc55cc'), speed: 0.85, shaderOpacity: 0.92 }
