    uvOrigin: [map.ox, map.oy],
    uvScale: [map.sx, map.sy],
    time: time * m.speed,
    colorBack: m.colorBack,
    colorTint: m.colorTint,
    repetition: m.repetition,
    softness: m.softness,
    shiftRed: m.shiftRed,
    shiftBlue: m.shiftBlue,
    distortion: m.distortion,
    contour: m.contour,
    angle: m.angle,
    opacityMul,
    ditherScale,
